from pathlib import Path
import json
p=Path(__file__).resolve().parents[1];source=p.parent/'parts/IV.body.linked.tex';s=source.read_text();patches=[]
def add(label,old,new,reason):
 assert s.count(old)==1,(label,s.count(old),old)
 patches.append(dict(label=label,old_text=old,new_text=new,reason=reason))
add('night:P3F.13',r'compact\_torsor.py checks both exact identities and the endpoint values.',r'The program \path{code/current_audits/audit_corrections/code/independent_IV_low_F_completion.py} subtracts the literal ordinary and cusp origins of \SeriesRef{night:P2.2}, checks both full differences and both endpoint values, and verifies the displayed small-resolution substitutions. The exact results are saved in \path{code/current_audits/audit_corrections/code/independent_IV_low_F_completion.json}.','Replace the absent historical program name by the actual fresh method, inputs and output; no analytic descent is inferred from the algebra.')
add('night:P3F.13',r'The normal-crossing chart suggested by the second Tate multiplier is XY=Qr after q=Q\^{}12, because q r\textsuperscript{12=\(Qr\)}12.',r'The second Tate multiplier gives the normal-crossing chart \(XY=Qr\) after \(q=Q^{12}\), since \(q r^{12}=(Qr)^{12}\).','Repair literal caret/textsuperscript corruption while preserving the exact parameter equation.')
add('night:P3F.13',r'The canonical quotient structure is spin\^{}c with determinant -K on that boundary; no claim that this compact product is spin is made.',r'The canonical quotient structure is \(\mathrm{spin}^c\), with determinant class \(-K\) on that boundary; its nonzero second Stiefel--Whitney class is detected by the compact sheet\textquotesingle s section.','Use proper mathematical superscripts and the already-proved characteristic obstruction, retaining the actual determinant class.')
add('night:P3F.15',r'After twelve iterations the W multiplier is eta\^{}12 zeta\^{}\(-66\) rho\textsuperscript{\(-12\)=rho}\(-12\), since the two first factors both equal-1.',r'After twelve iterations the \(W\)-multiplier is \(\eta^{12}\zeta^{-66}\rho^{-12}=\rho^{-12}\), since \(\eta^{12}=\zeta^{-66}=-1\).','Repair superscript corruption without changing the exact chronological phase.')
add('night:P3F.15',r'The twelve-step gauge has winding-12.',r'The twelve-step gauge has winding \(-12\). Formal Laurent-exponent transport in \path{code/current_audits/audit_corrections/code/independent_IV_low_F_completion.py} checks both node-chart units and the complete twelvefold phase; the retained output is \path{code/current_audits/audit_corrections/code/independent_IV_low_F_completion.json}.','Supply the new exact method and files for the labelled cyclic descent, without claiming an outer-cusp comparison.')
add('night:P3F.15',r'with reduced divisor Q=0 on those charts, would descend q=Q\^{}12 to a divisor of multiplicity twelve.',r'with reduced divisor \(Q=0\) on those charts, descends \(q=Q^{12}\) to a divisor of multiplicity twelve.','Keep the established valuation statement in actual mathematical notation.')
(p/'IV_low_F_final_format_patches.json').write_text(json.dumps(patches,ensure_ascii=False,indent=2)+'\n')
(p/'IV_low_F_final_format_receipt.json').write_text(json.dumps({'source':str(source),'patches':patches,'count':len(patches),'all_old_text_unique':True,'no_shared_edits':True},ensure_ascii=False,indent=2)+'\n')
print('Six uniquely matched F13/F15 proposals saved; no body edits.')
